# Independent bibliography audit: exact chapter/year/author and recurrence locator.
for r in R:
    if r['key']=='SGA4':
        r['year']='1973';r['title']='Théorie des topos et cohomologie étale des schémas, tome III (SGA 4)';r['volume']='305';r['doi']='10.1007/BFb0070714';r['date_scope']='Seminar1963–1964; cited tome III published1973 (tomes I–II appeared1972).'
        r['author']='Michael Artin and Pierre Deligne';r['editor']='Michael Artin and Alexander Grothendieck and Jean-Louis Verdier';r['locators']+='; the two cited exposés are by Michael Artin'
    if r['key']=='SGA6':r['editor']='Pierre Berthelot and Alexander Grothendieck and Luc Illusie';r['author']='Alexander Grothendieck (cited Exposé X appendix)'
    if r['key']=='SGA7II':r['editor']='Pierre Deligne and Nicholas Katz';r['author']='Pierre Deligne (cited integrality result)'
    if r['key']=='ArtebaniDolgachev2009':r['verification_scope']='Opened full author manuscript and read the level-3 Hesse formulas and group context. Integral-model identifications are separately checked in this run; the classical formulas alone are not used as their proof.'
    if r['key']=='Katz1976':r['locators']='Sections1.2–1.3 pp.464–468; Lemma1.3.6; Lemma4.0.7 and Question4.0.8 p.501'
    if r['key']=='MOHodgeCM2010':r['author']='Andrea Mori (question author); MathOverflow contributors'
    if r['key']=='DLMF27Partitions':r['title']='NIST DLMF Section27.14: Unrestricted Partitions';r['locators']='Equations27.14.2–6, including the partition recurrence27.14.6'
    if r['key']=='DLMF23Modular':r['title']='NIST DLMF Section23.15: Definitions'

# Avoid BibTeX syntax ambiguity while preserving Unicode text and mathematical scope.
def esc(x):return str(x).replace('\\','\\textbackslash{}').replace('{','(').replace('}',')').replace('%','\\%').replace('&','\\&')
out=['% Manually curated; note records successful opening, verification_scope records exactly what was checked.\n']
for r in R:
    out.append('@misc{'+r['key']+',\n'+',\n'.join('  '+k+' = {'+esc(v)+'}' for k,v in r.items() if k!='key')+'\n}\n')
(P/'references.bib').write_text('\n'.join(out))
(P/'reference_registry.json').write_text(json.dumps(R,ensure_ascii=False,indent=2)+'\n')
with (P/'reference_verification.tsv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=['key','note','url','locators','verification_scope','date_scope'],delimiter='\t',extrasaction='ignore');w.writeheader();w.writerows(R)
print(json.dumps({'references':len(R),'verified':sum(r['note']=='verified' for r in R),'unverified':sum(r['note']=='unverified' for r in R)}))
